#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int n, W;
    scanf("%d %d", &n, &W);
    std::vector<long long> dp(W + 1, 0);

    for (int i = 0; i < n; ++i) {
        int w; long long v;
        scanf("%d %lld", &w, &v);
        for (int j = w; j <= W; ++j)            // 正序：允许重复选取
            dp[j] = std::max(dp[j], dp[j - w] + v);
    }

    printf("%lld\n", dp[W]);
    return 0;
}
